    ('crates/iroha_core/src/state/canonical_runtime/acquisition.rs', 'method', 'RuntimeBlockAcquisition::initialize', ('    pub(super) fn initialize(\n        &mut self,\n        replacement: bool,\n    ) -> Result<(), storage_transactions::MembershipAdmissionError> {\n        assert!(!self.started, "original State acquisition is one-shot");\n        self.started = true;\n        self.world = Some(if replacement {\n            self.target.world.block_and_revert()\n        } else {\n            self.target.world.block()\n        });\n        self.transactions = Some(\n            self.target\n                .transactions\n                .attach_prepared(&mut self.membership)?,\n        );\n        self.cells.initialize(if replacement {\n            BlockMode::Replace\n        } else {\n            BlockMode::Ordinary\n        });\n        self.complete = true;\n        Ok(())\n    }',)),
