    ('crates/mv/src/cell/detached_publication.rs', 'enum', 'Phase', ("enum Phase<'a, V: Value, A, I, C: Send + Sync + 'static> {\n    Original(Detached<V, A, C>),\n    Acquiring {\n        revert: Role<'a, Option<V>, C>,\n        blocks: Role<'a, V, C>,\n        metadata: DetachedMetadata<A>,\n    },\n    Prepared(PreparedPublication<'a, V, A, I, C>),\n    Empty,\n}",)),
