    ('crates/iroha_core/src/state.rs', 'method', 'State::lane_consensus_lifecycle_snapshot_with_cursors', ("    fn lane_consensus_lifecycle_snapshot_with_cursors(\n        &self,\n        cursors: &mut crate::publication_rwlock::DeferredPublicationRwLock<'_, DaShardCursorIndex>,\n    ) -> LaneConsensusLifecycleSnapshot {\n        loop {\n            let generation_before = self.state_view_generation();\n            if generation_before % 2 != 0 {\n                std::thread::yield_now();\n                continue;\n            }\n            let nexus = self.nexus_snapshot();\n            let incarnations = self.lane_incarnations_snapshot();\n            let activation_heights = self.lane_incarnation_activation_heights_snapshot();\n            let mut reset_heights = cursors.read().canonical_reset_heights().clone();\n            for (lane_id, activation_height) in &activation_heights {\n                if *activation_height == 0 {\n                    continue;\n                }\n                reset_heights\n                    .entry(*lane_id)\n                    .and_modify(|height| *height = (*height).max(*activation_height))\n                    .or_insert(*activation_height);\n            }\n            let generation_after = self.state_view_generation();\n            if is_stable_state_view_generation(generation_before, generation_after) {\n                return LaneConsensusLifecycleSnapshot {\n                    nexus,\n                    incarnations,\n                    activation_heights,\n                    reset_heights,\n                };\n            }\n            std::thread::yield_now();\n        }\n    }",)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::publish_prevalidated_lane_relay', ('    fn publish_prevalidated_lane_relay(\n        &self,\n        envelope: &LaneRelayEnvelope,\n        relay_proposal_height: u64,\n    ) -> core::result::Result<LaneRelayInsert, LaneRelayError> {\n        // Serialize the final authenticated lifecycle recheck and cache\n        // insertion with geometry archive/removal, catalog publication, and\n        // lane-scoped cache pruning. If admission wins this fence, retirement\n        // observes the relay as a drain blocker. If retirement wins, this\n        // post-fence snapshot rejects the retired incarnation. Raw/unvalidated\n        // cache noise never crosses this fence and therefore cannot veto\n        // Byzantine-tolerant retirement.\n        let mut relay_releases = self.lane_relays.defer_notifications();\n        let mut cursor_releases = self.da_shard_cursors.defer_notifications();\n        let lifecycle_guard = self.lane_lifecycle_lock.lock();\n        let current_lifecycle =\n            self.lane_consensus_lifecycle_snapshot_with_cursors(&mut cursor_releases);\n        let current_incarnation = current_lifecycle\n            .incarnations\n            .get(&envelope.lane_id)\n            .copied()\n            .ok_or(LaneRelayError::UnknownLane(envelope.lane_id))?;\n        if current_incarnation != envelope.lane_incarnation {\n            return Err(LaneRelayError::LaneIncarnationMismatch {\n                lane: envelope.lane_id,\n                expected: current_incarnation,\n                actual: envelope.lane_incarnation,\n            });\n        }\n        if !current_lifecycle.lane_route_and_incarnation_matches(\n            envelope.lane_id,\n            envelope.dataspace_id,\n            relay_proposal_height,\n            envelope.lane_incarnation,\n        ) {\n            return Err(LaneRelayError::StaleLaneIncarnation {\n                lane: envelope.lane_id,\n                reset_height: current_lifecycle\n                    .reset_heights\n                    .get(&envelope.lane_id)\n                    .copied()\n                    .unwrap_or(relay_proposal_height),\n                relay_height: relay_proposal_height,\n            });\n        }\n        let inserted = {\n            let mut guard = relay_releases.write();\n            guard.insert(envelope.clone())?\n        };\n        if matches!(\n            inserted,\n            LaneRelayInsert::Inserted | LaneRelayInsert::Replaced\n        ) {\n            // Retirement prunes both caches under this fence. Publishing status\n            // after unlocking could resurrect an already retired incarnation.\n            crate::sumeragi::status::push_lane_relay_envelope(envelope.clone());\n        }\n        drop(lifecycle_guard);\n        #[cfg(feature = "telemetry")]\n        if matches!(\n            inserted,\n            LaneRelayInsert::Inserted | LaneRelayInsert::Replaced\n        ) {\n            let head_height = u64::try_from(self.block_hashes.view().len()).unwrap_or(0);\n            self.telemetry.record_lane_relay_finality(\n                envelope.lane_id,\n                envelope.dataspace_id,\n                relay_proposal_height,\n                head_height,\n                envelope.rbc_bytes_total,\n            );\n        }\n        Ok(inserted)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::record_da_lane_reset_watermarks', ("    fn record_da_lane_reset_watermarks(\n        &self,\n        lanes_to_reset: &BTreeSet<LaneId>,\n        reset_height: u64,\n        releases: &mut LaneLifecycleReleases<'_>,\n    ) {\n        if lanes_to_reset.is_empty() || reset_height == 0 {\n            return;\n        }\n        {\n            let mut cursors = releases.shard_cursors.write();\n            cursors.mark_lanes_canonically_reset(lanes_to_reset, reset_height);\n        }\n        self.persist_lane_lifecycle_cursor_journal(releases);\n    }",)),
