    ('crates/iroha_core/src/state.rs', 'method', 'State::merge_consensus_snapshot_inner', ('    fn merge_consensus_snapshot_inner(\n        &self,\n        entry: Option<&MergeLedgerEntry>,\n    ) -> Result<MergeConsensusSnapshot, MergeLedgerCommitError> {\n        let mut releases = LaneLifecycleReleases::new(self);\n        self.merge_consensus_snapshot_inner_with_releases(entry, &mut releases)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::merge_consensus_snapshot_inner_with_releases', ("    fn merge_consensus_snapshot_inner_with_releases(\n        &self,\n        entry: Option<&MergeLedgerEntry>,\n        releases: &mut LaneLifecycleReleases<'_>,\n    ) -> Result<MergeConsensusSnapshot, MergeLedgerCommitError> {\n        loop {\n            let generation_before = self.state_view_generation();\n            if generation_before % 2 != 0 {\n                std::thread::yield_now();\n                continue;\n            }\n            let (committed_height, latest_block_hash) = {\n                let block_hashes = self.block_hashes.view_retaining(&mut releases.hashes);\n                (\n                    u64::try_from(block_hashes.len()).unwrap_or(u64::MAX),\n                    block_hashes.last().copied(),\n                )\n            };\n            let nexus = self.nexus_snapshot();\n            let incarnations = self.lane_incarnations_snapshot();\n            let activation_heights = self.lane_incarnation_activation_heights_snapshot();\n            let mut reset_heights = releases\n                .shard_cursors\n                .read()\n                .canonical_reset_heights()\n                .clone();\n            for (lane_id, activation_height) in &activation_heights {\n                if *activation_height == 0 {\n                    continue;\n                }\n                reset_heights\n                    .entry(*lane_id)\n                    .and_modify(|height| *height = (*height).max(*activation_height))\n                    .or_insert(*activation_height);\n            }\n            let (admission, admission_validation) = {\n                let admission = releases.merge_admission.read();\n                let validation = entry.map(|entry| admission.validate_next(entry));\n                (admission.snapshot(), validation)\n            };\n            let generation_after = self.state_view_generation();\n            if is_stable_state_view_generation(generation_before, generation_after) {\n                if let Some(validation) = admission_validation {\n                    validation?;\n                }\n                return Ok(MergeConsensusSnapshot {\n                    generation: generation_after,\n                    lifecycle: LaneConsensusLifecycleSnapshot {\n                        nexus,\n                        incarnations,\n                        activation_heights,\n                        reset_heights,\n                    },\n                    admission,\n                    committed_height,\n                    latest_block_hash,\n                });\n            }\n            std::thread::yield_now();\n        }\n    }",)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::unmerged_merge_admissible_relay_progress_with_releases', ('    fn unmerged_merge_admissible_relay_progress_with_releases(\n        &self,\n        lane_id: LaneId,\n        dataspace_id: DataSpaceId,\n        releases: &mut LaneLifecycleReleases<\'_>,\n    ) -> Option<(u64, u64)> {\n        if self.ensure_merge_history_available().is_err() {\n            return None;\n        }\n        let consensus = self\n            .merge_consensus_snapshot_inner_with_releases(None, releases)\n            .expect("merge snapshot without entry validation cannot fail");\n        let lifecycle = &consensus.lifecycle;\n        let lane_incarnation = lifecycle.incarnations.get(&lane_id).copied()?;\n        let expected_height = expected_next_merge_lane_height(\n            &consensus.admission.latest_lane_snapshots,\n            lane_id,\n            dataspace_id,\n            lane_incarnation,\n        )?;\n        let relays = releases.relays.read().snapshot();\n        let latest_unmerged_height = relays\n            .into_iter()\n            .filter(|relay| {\n                let proposal_height = relay.block_header.height().get();\n                relay.lane_id == lane_id\n                    && relay.dataspace_id == dataspace_id\n                    && relay.has_merge_admission_material()\n                    && self.verify_lane_relay_fastpq_record(relay).is_ok()\n                    && relay.lane_incarnation == lane_incarnation\n                    && lifecycle.lane_route_and_incarnation_matches(\n                        lane_id,\n                        dataspace_id,\n                        proposal_height,\n                        lane_incarnation,\n                    )\n            })\n            .map(|relay| relay.block_height)\n            .filter(|height| *height >= expected_height)\n            .max()?;\n        Some((expected_height, latest_unmerged_height))\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::lane_has_drain_blocking_evidence', ('    pub(crate) fn lane_has_drain_blocking_evidence(\n        &self,\n        lane_id: LaneId,\n        dataspace_id: DataSpaceId,\n        lane_incarnation: Hash,\n    ) -> Result<bool, MergeLedgerCommitError> {\n        let mut releases = LaneLifecycleReleases::new(self);\n        self.lane_has_drain_blocking_evidence_with_releases(\n            lane_id,\n            dataspace_id,\n            lane_incarnation,\n            &mut releases,\n        )\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::lane_has_drain_blocking_evidence_with_releases', ("    fn lane_has_drain_blocking_evidence_with_releases(\n        &self,\n        lane_id: LaneId,\n        dataspace_id: DataSpaceId,\n        lane_incarnation: Hash,\n        releases: &mut LaneLifecycleReleases<'_>,\n    ) -> Result<bool, MergeLedgerCommitError> {\n        let lifecycle =\n            self.lane_consensus_lifecycle_snapshot_with_cursors(&mut releases.shard_cursors);\n        Ok(self\n            .unmerged_merge_admissible_relay_progress_with_releases(lane_id, dataspace_id, releases)\n            .is_some()\n            || self\n                .unapplied_lane_block_artifact_heights_snapshot_cached_with_lifecycle(&lifecycle)?\n                .contains_key(&(lane_id, dataspace_id))\n            || self\n                .unapplied_certified_lane_block_heights_snapshot_cached_with_lifecycle(&lifecycle)?\n                .contains_key(&(lane_id, dataspace_id))\n            || self\n                .native_amx_participant_frontiers_pending_durable_evidence_snapshot_with_lifecycle(\n                    &lifecycle,\n                )?\n                .iter()\n                .any(|marker| {\n                    marker.lane_id == lane_id\n                        && marker.dataspace_id == dataspace_id\n                        && marker.lane_incarnation == lane_incarnation\n                })\n            || self.pending_queue_plan_admission_blocks_lane_drain_with_releases(\n                lane_id,\n                dataspace_id,\n                lane_incarnation,\n                releases,\n            )?\n            || self.queue_plan_pending_route_obligation_blocks_lane_drain(\n                lane_id,\n                dataspace_id,\n                lane_incarnation,\n            )?\n            || self.kura.pending_certified_merge_work_for_lane(\n                lane_id,\n                dataspace_id,\n                lane_incarnation,\n            )?)\n    }",)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::pending_queue_plan_admission_blocks_lane_drain_with_releases', ('    fn pending_queue_plan_admission_blocks_lane_drain_with_releases(\n        &self,\n        lane_id: LaneId,\n        dataspace_id: DataSpaceId,\n        lane_incarnation: Hash,\n        releases: &mut LaneLifecycleReleases<\'_>,\n    ) -> Result<bool, MergeLedgerCommitError> {\n        let pending = self\n            .kura\n            .pending_queue_plan_admission_certificates_bounded(\n                self.kura.pending_queue_plan_admission_capacity(),\n            )?;\n        let carrier_height = u64::try_from(self.committed_height())\n            .ok()\n            .and_then(|height| height.checked_add(1))\n            .ok_or_else(|| {\n                MergeLedgerCommitError::ExecutionMarkerConflict(\n                    "lane drain observation carrier height overflow".to_owned(),\n                )\n            })?;\n        for (_, bytes) in pending {\n            let admission = self.authenticate_pending_queue_plan_admission(&bytes)?;\n            let disposition = {\n                let state_view = self.view_with_index_releases(releases);\n                Self::classify_pending_queue_plan_admission_in_view(\n                    &state_view,\n                    &admission,\n                    carrier_height,\n                )?\n            };\n            if matches!(\n                disposition,\n                PendingQueuePlanAdmissionDisposition::ExactPending\n                    | PendingQueuePlanAdmissionDisposition::Applied\n                    | PendingQueuePlanAdmissionDisposition::DefinitiveConflict\n                    | PendingQueuePlanAdmissionDisposition::Stale\n            ) {\n                continue;\n            }\n            if admission\n                .certificate\n                .binding\n                .admission_context\n                .route_incarnations\n                .iter()\n                .any(|bound| {\n                    bound.leg.route.lane_id == lane_id\n                        && bound.leg.route.dataspace_id == dataspace_id\n                        && bound.lane_incarnation == lane_incarnation\n                })\n            {\n                return Ok(true);\n            }\n        }\n        Ok(false)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::try_view_once', ("    pub(crate) fn try_view_once(&self) -> Result<Option<StateView<'_>>, LaneLifecycleError> {\n        StateViewReleases::new(self).try_view_once()\n    }",)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::view_with_index_releases', ('    fn view_with_index_releases(&self, releases: &mut LaneLifecycleReleases<\'_>) -> StateView<\'_> {\n        loop {\n            if let Some(view) = self\n                .try_view_once_with_index_releases(\n                    &mut releases.header,\n                    &mut releases.manifests,\n                    &mut releases.sccp,\n                    &mut releases.hashes,\n                    &mut releases.membership,\n                )\n                .expect("persisted canonical runtime projection must be valid")\n            {\n                return view;\n            }\n            self.note_view_generation_contention(core::panic::Location::caller());\n            std::thread::yield_now();\n        }\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::try_view_once_with_index_releases', ('    fn try_view_once_with_index_releases(\n        &self,\n        header: &mut crate::publication_rwlock::DeferredPublicationRwLock<\'_, Option<BlockHeader>>,\n        manifests: &mut crate::publication_rwlock::DeferredPublicationRwLock<\n            \'_,\n            LaneManifestRegistryHandle,\n        >,\n        sccp: &mut crate::publication_lock::DeferredPublicationFence<\'_, SccpRegistryCache>,\n        hashes: &mut Option<concread::release::DeferredReleaseBatch>,\n        membership: &mut concread::release::DeferredReleaseBatch,\n    ) -> Result<Option<StateView<\'_>>, LaneLifecycleError> {\n        const STATE_VIEW_LOG_THRESHOLD: Duration = Duration::from_millis(10);\n        let caller = core::panic::Location::caller();\n        let total_start = Instant::now();\n        {\n            let generation_before = self.state_view_generation();\n            if generation_before % 2 != 0 {\n                return Ok(None);\n            }\n            let block_hashes_start = Instant::now();\n            let block_hashes = self.block_hashes.view_retaining(hashes);\n            let block_hashes_wait = block_hashes_start.elapsed();\n            let latest_hash = block_hashes.last().copied();\n            let cached_header = header.read().clone();\n            let query_ledger_time_ms =\n                self.latest_block_creation_time_ms_from_header(latest_hash, cached_header.as_ref());\n            let nexus_start = Instant::now();\n            let canonical_runtime = self.canonical_runtime.view();\n            let canonical_runtime_predecessor = self.canonical_runtime.predecessor_view();\n            let nexus_wait = nexus_start.elapsed();\n            let world_start = Instant::now();\n            let mut world = self.world.view();\n            let baseline = manifests.read().clone();\n            let projection = self.project_canonical_runtime_with_manifests(\n                canonical_runtime.get(),\n                &world,\n                &baseline,\n            );\n            let world_wait = world_start.elapsed();\n            let transactions_start = Instant::now();\n            let transactions = self\n                .transactions\n                .view_retaining(membership)\n                .expect("original membership reader source must be healthy");\n            let transactions_wait = transactions_start.elapsed();\n            let commit_topology_start = Instant::now();\n            let commit_topology = self.commit_topology.view();\n            let commit_topology_wait = commit_topology_start.elapsed();\n            let prev_commit_topology_start = Instant::now();\n            let prev_commit_topology = self.prev_commit_topology.view();\n            let lane_consensus_contexts = self.lane_consensus_contexts.view().get().clone();\n            let prev_commit_topology_wait = prev_commit_topology_start.elapsed();\n            let sccp_registry = Self::sccp_registry_snapshot_from_cache(\n                world.sccp_registry.get(),\n                &mut sccp.lock(),\n            );\n            let generation_after = self.state_view_generation();\n            if !is_stable_state_view_generation(generation_before, generation_after) {\n                drop(prev_commit_topology);\n                drop(commit_topology);\n                drop(transactions);\n                drop(world);\n                return Ok(None);\n            }\n            let projection = projection?;\n            let canonical_runtime::CanonicalRuntimeProjection {\n                nexus,\n                incarnations: lane_incarnations,\n                activation_heights: lane_incarnation_activation_heights,\n                lineage: lane_incarnation_lineage,\n                samples: _,\n                manifests: lane_manifests,\n                privacy: _,\n            } = projection;\n            world.dataspace_catalog = nexus.dataspace_catalog.clone();\n            let total_wait = total_start.elapsed();\n            let (mut max_component, mut max_wait) = ("block_hashes", block_hashes_wait);\n            if world_wait > max_wait {\n                max_component = "world";\n                max_wait = world_wait;\n            }\n            if transactions_wait > max_wait {\n                max_component = "transactions";\n                max_wait = transactions_wait;\n            }\n            if commit_topology_wait > max_wait {\n                max_component = "commit_topology";\n                max_wait = commit_topology_wait;\n            }\n            if prev_commit_topology_wait > max_wait {\n                max_component = "prev_commit_topology";\n                max_wait = prev_commit_topology_wait;\n            }\n            if nexus_wait > max_wait {\n                max_component = "nexus";\n                max_wait = nexus_wait;\n            }\n            if max_wait >= STATE_VIEW_LOG_THRESHOLD {\n                debug!(\n                    caller = %caller,\n                    max_component,\n                    max_wait_us = max_wait.as_micros(),\n                    total_wait_us = total_wait.as_micros(),\n                    block_hashes_wait_us = block_hashes_wait.as_micros(),\n                    world_wait_us = world_wait.as_micros(),\n                    transactions_wait_us = transactions_wait.as_micros(),\n                    commit_topology_wait_us = commit_topology_wait.as_micros(),\n                    prev_commit_topology_wait_us = prev_commit_topology_wait.as_micros(),\n                    nexus_wait_us = nexus_wait.as_micros(),\n                    state_view_generation = generation_after,\n                    "state view acquisition slow or retried"\n                );\n            }\n            return Ok(Some(StateView {\n                canonical_runtime,\n                canonical_runtime_predecessor,\n                world,\n                block_hashes,\n                merge_ledger: &self.merge_ledger,\n                transactions,\n                commit_topology,\n                prev_commit_topology,\n                lane_consensus_contexts,\n                ivm: &self.ivm,\n                pipeline_ivm_prepared_cache: self.pipeline_ivm_prepared_cache.read().clone(),\n                da_receipt_cursors: &self.da_receipt_cursors,\n                da_shard_cursors: &self.da_shard_cursors,\n                kura: &self.kura,\n                query_handle: &self.query_handle,\n                query_ledger_time_ms,\n                accounts_snapshot_cache: SyncOnceCell::new(),\n                #[cfg(feature = "telemetry")]\n                telemetry: &self.telemetry,\n                pipeline: self.pipeline.clone(),\n                oracle: self.oracle.clone(),\n                crypto: self.crypto(),\n                nexus,\n                lane_incarnations,\n                lane_incarnation_lineage,\n                lane_incarnation_activation_heights,\n                lane_manifests,\n                fraud_monitoring: self.fraud_monitoring.clone(),\n                zk: self.zk.clone(),\n                sccp_registry,\n                gov: self.gov.clone(),\n                content: self.content.clone(),\n                settlement: self.settlement.clone(),\n                kagemusha_v1_runtime_verifier: Arc::clone(&self.kagemusha_v1_runtime_verifier),\n                settlement_engine: self.settlement_engine.clone(),\n                chain_id: self.chain_id.clone(),\n                network_id: self.network_id,\n                created_at: Instant::now(),\n            }));\n        }\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::latest_block_creation_time_ms_fast', ('    pub fn latest_block_creation_time_ms_fast(&self) -> Option<u64> {\n        let latest_hash = self.latest_block_hash_fast();\n        let cached_header = self.latest_block_header.read().clone();\n        self.latest_block_creation_time_ms_from_header(latest_hash, cached_header.as_ref())\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::latest_block_creation_time_ms_from_header', ('    fn latest_block_creation_time_ms_from_header(\n        &self,\n        latest_hash: Option<HashOf<BlockHeader>>,\n        cached_header: Option<&BlockHeader>,\n    ) -> Option<u64> {\n        let cached = cached_header\n            .filter(|header| Some(header.hash()) == latest_hash)\n            .map(|header| u64::try_from(header.creation_time().as_millis()).unwrap_or(u64::MAX));\n        cached.or_else(|| {\n            let anchor = self\n                .authenticated_snapshot_v2_bootstrap\n                .as_ref()?\n                .context\n                .snapshot_bootstrap\n                .as_ref()?;\n            (Some(anchor.snapshot_block_hash) == latest_hash)\n                .then_some(anchor.snapshot_block_creation_time_ms)\n        })\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::sccp_registry_snapshot_from_world', ('    fn sccp_registry_snapshot_from_world(\n        &self,\n        wire: &SccpOnChainRegistryV1,\n    ) -> Arc<ValidatedSccpRegistryV1> {\n        let mut cache = self.sccp_registry_cache.lock();\n        Self::sccp_registry_snapshot_from_cache(wire, &mut cache)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::sccp_registry_snapshot_from_cache', ('    fn sccp_registry_snapshot_from_cache(\n        wire: &SccpOnChainRegistryV1,\n        cache: &mut SccpRegistryCache,\n    ) -> Arc<ValidatedSccpRegistryV1> {\n        if cache.matches(wire) {\n            return Arc::clone(&cache.registry);\n        }\n        let registry = ValidatedSccpRegistryV1::try_from_wire(wire.clone()).unwrap_or_else(\n            |error| {\n                panic!(\n                    "consensus SCCP registry invariant violated after admission or snapshot validation: {error}"\n                )\n            },\n        );\n        cache.registry = Arc::clone(&registry);\n        registry\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::native_amx_participant_application_snapshot', ('    fn native_amx_participant_application_snapshot(\n        &self,\n    ) -> Result<NativeAmxParticipantApplicationSnapshot, MergeLedgerCommitError> {\n        let lifecycle = self.lane_consensus_lifecycle_snapshot();\n        self.native_amx_participant_application_snapshot_with_lifecycle(&lifecycle)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::native_amx_participant_application_snapshot_with_lifecycle', ('    fn native_amx_participant_application_snapshot_with_lifecycle(\n        &self,\n        lifecycle: &LaneConsensusLifecycleSnapshot,\n    ) -> Result<NativeAmxParticipantApplicationSnapshot, MergeLedgerCommitError> {\n        use crate::kura::NativeAmxParticipantApplicationObservation;\n\n        let world = self.world.view();\n        let mut snapshot = NativeAmxParticipantApplicationSnapshot::default();\n        for lane in lifecycle.nexus.lane_catalog.lanes() {\n            let incarnation = lifecycle\n                .incarnations\n                .get(&lane.id)\n                .copied()\n                .ok_or_else(|| {\n                    MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "active Native AMX participant route {} has no incarnation",\n                        lane.id.as_u32(),\n                    ))\n                })?;\n            // Read before marker filtering: a valid pending carrier may be\n            // durable before its replicated frontier is visible in this State.\n            let history = self\n                .kura\n                .consensus_storage_read(\n                    self.kura\n                        .read_native_amx_participant_application_history(lane.id),\n                )\n                .map_err(MergeLedgerCommitError::Persistence)?;\n            let marker = Self::canonical_native_amx_participant_frontier_from_world(\n                &world,\n                lane.id,\n                lane.dataspace_id,\n                incarnation,\n            )?;\n            if let Some(marker) = marker {\n                if !lifecycle.lane_route_and_incarnation_matches(\n                    lane.id,\n                    lane.dataspace_id,\n                    marker.application_block_height,\n                    incarnation,\n                ) {\n                    return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "Native AMX participant frontier for lane {} is stale at application height {}",\n                        lane.id.as_u32(),\n                        marker.application_block_height,\n                    )));\n                }\n            }\n            if let Some(marker) = marker {\n                Self::validate_native_amx_participant_shared_frontier(&world, &marker)?;\n            }\n            let route = (lane.id, lane.dataspace_id);\n            for (height, observation) in history.entries() {\n                let (\n                    observed_lane,\n                    observed_dataspace,\n                    observed_incarnation,\n                    application_height,\n                    marker_matches,\n                ) = match observation {\n                    NativeAmxParticipantApplicationObservation::Applied(receipt)\n                    | NativeAmxParticipantApplicationObservation::PendingTipMetadata(receipt)\n                    | NativeAmxParticipantApplicationObservation::PendingManifestRepair(receipt) => {\n                        let descriptor = &receipt.participant_proposal.descriptor;\n                        (\n                            descriptor.lane_id,\n                            descriptor.dataspace_id,\n                            descriptor.lane_incarnation,\n                            receipt.application_block_height,\n                            marker.is_none_or(|marker| {\n                                marker.lane_block_height != height\n                                    || Self::native_amx_participant_receipt_matches_frontier(\n                                        receipt, marker,\n                                    )\n                            }),\n                        )\n                    }\n                    NativeAmxParticipantApplicationObservation::PendingReceiptRepair(manifest) => {\n                        let leaf = &manifest.leaf;\n                        (leaf.lane_id, leaf.dataspace_id, leaf.lane_incarnation,\n                            leaf.application_block_height, marker.is_none_or(|marker| {\n                                marker.lane_block_height != height\n                                    || crate::kura::Kura::native_amx_manifest_leaf_matches_frontier_marker(leaf, &marker)\n                            }))\n                    }\n                };\n                if observed_lane != lane.id\n                    || observed_dataspace != lane.dataspace_id\n                    || observed_incarnation != incarnation\n                    || !lifecycle.lane_route_and_incarnation_matches(\n                        observed_lane,\n                        observed_dataspace,\n                        application_height,\n                        observed_incarnation,\n                    )\n                {\n                    return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "Native AMX durable history for lane {} disagrees with the active State route at height {height}",\n                        lane.id.as_u32(),\n                    )));\n                }\n                if !marker_matches {\n                    return Err(MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "Native AMX durable evidence conflicts with its replicated frontier for lane {} height {height}",\n                        lane.id.as_u32(),\n                    )));\n                }\n                if !matches!(\n                    observation,\n                    NativeAmxParticipantApplicationObservation::Applied(_)\n                ) || marker.is_none_or(|marker| height > marker.lane_block_height)\n                {\n                    snapshot\n                        .blocked\n                        .entry(route)\n                        .and_modify(|blocked| *blocked = (*blocked).max(height))\n                        .or_insert(height);\n                } else {\n                    snapshot.applied_slots.insert((\n                        lane.id,\n                        lane.dataspace_id,\n                        incarnation,\n                        height,\n                    ));\n                }\n            }\n            let Some(marker) = marker else {\n                continue;\n            };\n            if matches!(\n                history.get(marker.lane_block_height),\n                Some(NativeAmxParticipantApplicationObservation::Applied(_))\n            ) {\n                snapshot.applied.push(marker);\n            } else {\n                snapshot.repair.push(marker);\n                snapshot\n                    .blocked\n                    .entry(route)\n                    .and_modify(|blocked| *blocked = (*blocked).max(marker.lane_block_height))\n                    .or_insert(marker.lane_block_height);\n            }\n        }\n        Ok(snapshot)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::native_amx_participant_frontiers_pending_durable_evidence_snapshot', ('    pub(crate) fn native_amx_participant_frontiers_pending_durable_evidence_snapshot(\n        &self,\n    ) -> Result<Vec<AppliedNativeAmxParticipantFrontierMarker>, MergeLedgerCommitError> {\n        let lifecycle = self.lane_consensus_lifecycle_snapshot();\n        self.native_amx_participant_frontiers_pending_durable_evidence_snapshot_with_lifecycle(\n            &lifecycle,\n        )\n    }',)),
