    ('crates/iroha_core/src/state.rs', 'method', 'State::unapplied_lane_block_artifact_heights_snapshot_cached', ('    pub(crate) fn unapplied_lane_block_artifact_heights_snapshot_cached(\n        &self,\n    ) -> Result<BTreeMap<(LaneId, DataSpaceId), u64>, MergeLedgerCommitError> {\n        let lifecycle = self.lane_consensus_lifecycle_snapshot();\n        self.unapplied_lane_block_artifact_heights_snapshot_cached_with_lifecycle(&lifecycle)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::unapplied_lane_block_artifact_heights_snapshot_cached_with_lifecycle', ('    fn unapplied_lane_block_artifact_heights_snapshot_cached_with_lifecycle(\n        &self,\n        lifecycle: &LaneConsensusLifecycleSnapshot,\n    ) -> Result<BTreeMap<(LaneId, DataSpaceId), u64>, MergeLedgerCommitError> {\n        let mut heights = BTreeMap::new();\n        for (lane_id, dataspace_id) in Self::lane_block_artifact_routes(&lifecycle.nexus) {\n            let Some(artifact) = self\n                .kura\n                .latest_lane_block_artifact_matching(lane_id, |artifact| {\n                    let ownership = &artifact.ownership;\n                    ownership.dataspace_id == dataspace_id\n                        && lifecycle.lane_route_and_incarnation_matches(\n                            lane_id,\n                            dataspace_id,\n                            ownership.proposal_height,\n                            ownership.lane_incarnation,\n                        )\n                })\n                .map_err(|error| {\n                    MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "failed to authenticate unapplied lane artifact tip: {error}"\n                    ))\n                })?\n            else {\n                continue;\n            };\n            let lane_block_height = artifact.ownership.lane_block_height;\n            if self.lane_block_artifact_is_applied_or_snapshot_anchored(&artifact)? {\n                continue;\n            }\n            heights.insert((lane_id, dataspace_id), lane_block_height);\n        }\n        for (route, lane_block_height) in self\n            .unapplied_native_amx_participant_control_heights_snapshot_with_lifecycle(lifecycle)?\n        {\n            heights\n                .entry(route)\n                .and_modify(|height| *height = (*height).max(lane_block_height))\n                .or_insert(lane_block_height);\n        }\n        Ok(heights)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::unapplied_certified_lane_block_heights_snapshot_cached', ('    pub(crate) fn unapplied_certified_lane_block_heights_snapshot_cached(\n        &self,\n    ) -> Result<BTreeMap<(LaneId, DataSpaceId), u64>, MergeLedgerCommitError> {\n        let lifecycle = self.lane_consensus_lifecycle_snapshot();\n        self.unapplied_certified_lane_block_heights_snapshot_cached_with_lifecycle(&lifecycle)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::unapplied_certified_lane_block_heights_snapshot_cached_with_lifecycle', ('    fn unapplied_certified_lane_block_heights_snapshot_cached_with_lifecycle(\n        &self,\n        lifecycle: &LaneConsensusLifecycleSnapshot,\n    ) -> Result<BTreeMap<(LaneId, DataSpaceId), u64>, MergeLedgerCommitError> {\n        let mut heights = BTreeMap::new();\n        for (lane_id, dataspace_id) in Self::lane_block_artifact_routes(&lifecycle.nexus) {\n            let Some(artifact) = self\n                .kura\n                .latest_certified_lane_block_artifact_matching(lane_id, |artifact| {\n                    let descriptor = &artifact.proposal.descriptor;\n                    descriptor.dataspace_id == dataspace_id\n                        && lifecycle.lane_route_and_incarnation_matches(\n                            lane_id,\n                            dataspace_id,\n                            descriptor.proposal_height,\n                            descriptor.lane_incarnation,\n                        )\n                })\n                .map_err(|error| {\n                    MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                        "certified lane unapplied frontier read failed: {error}"\n                    ))\n                })?\n            else {\n                continue;\n            };\n            if self.certified_lane_block_artifact_is_applied_or_snapshot_anchored(&artifact)? {\n                continue;\n            }\n            heights.insert(\n                (lane_id, dataspace_id),\n                artifact.proposal.descriptor.lane_block_height,\n            );\n        }\n        Ok(heights)\n    }',)),
    ('crates/iroha_core/src/state.rs', 'method', 'State::unapplied_certified_lane_block_height_with_lifecycle', ('    fn unapplied_certified_lane_block_height_with_lifecycle(\n        &self,\n        lane_id: LaneId,\n        dataspace_id: DataSpaceId,\n        lifecycle: &LaneConsensusLifecycleSnapshot,\n    ) -> Result<Option<u64>, MergeLedgerCommitError> {\n        let Some(artifact) = self\n            .kura\n            .latest_certified_lane_block_artifact_matching(lane_id, |artifact| {\n                let descriptor = &artifact.proposal.descriptor;\n                descriptor.dataspace_id == dataspace_id\n                    && lifecycle.lane_route_and_incarnation_matches(\n                        lane_id,\n                        dataspace_id,\n                        descriptor.proposal_height,\n                        descriptor.lane_incarnation,\n                    )\n            })\n            .map_err(|error| {\n                MergeLedgerCommitError::ExecutionMarkerConflict(format!(\n                    "certified lane retirement frontier read failed: {error}"\n                ))\n            })?\n        else {\n            return Ok(None);\n        };\n        let height = artifact.proposal.descriptor.lane_block_height;\n        Ok(\n            (!self.certified_lane_block_artifact_is_applied_or_snapshot_anchored(&artifact)?)\n                .then_some(height),\n        )\n    }',)),
    ('crates/iroha_core/src/state/geometry_publication.rs', 'method', 'State::resume_lane_geometry_publication', ('    fn resume_lane_geometry_publication(\n        &self,\n        request: &crate::kura::ReplayGeometryBindingRequest<\'_>,\n        replaced: &BTreeSet<LaneId>,\n        certified: &BTreeMap<(LaneId, DataSpaceId, Hash), LaneDrainFrontierV1>,\n        mut startup: Option<&mut crate::kura::StartupReplayGeometryTransition>,\n        mut releases: Option<&mut LaneLifecycleReleases<\'_>>,\n    ) -> Result<(), LaneLifecycleError> {\n        let publish_cursors = releases.is_some();\n        let mut slot = self.geometry_publication.lock();\n        if let Some(original) = slot.as_ref() {\n            let startup_matches = match (&original.startup_owner, startup.as_deref()) {\n                (None, None) => true,\n                (Some(owner), Some(transition)) => {\n                    Arc::ptr_eq(owner, &transition.original_owner_identity())\n                }\n                _ => false,\n            };\n            if original.publish_cursors != publish_cursors\n                || !lane_config_entries_match(&original.previous, request.previous)\n                || !lane_config_entries_match(&original.current, request.updated)\n                || original.previous_incarnations != *request.previous_incarnations\n                || original.current_incarnations != *request.updated_incarnations\n                || original.previous_activation_heights != *request.previous_activation_heights\n                || original.current_activation_heights != *request.updated_activation_heights\n                || original.previous_lineage_root != request.previous_lineage_root\n                || original.current_lineage_root != request.updated_lineage_root\n                || original.transition_height != request.transition_height\n                || original.replaced != *replaced\n                || original.certified != *certified\n                || !startup_matches\n                || original\n                    .raw\n                    .as_ref()\n                    .is_some_and(|raw| !raw.matches_request(request, replaced, certified))\n            {\n                return Err(LaneLifecycleError::Storage(\n                    "another exact lane geometry operation is already retained".to_owned(),\n                ));\n            }\n        } else {\n            if startup.is_some() && !certified.is_empty() {\n                return Err(LaneLifecycleError::Storage(\n                    "startup replay cannot replace live certified drain ownership".to_owned(),\n                ));\n            }\n            *slot = Some(LaneGeometryPublication {\n                raw: None,\n                tiered: None,\n                certified: certified.clone(),\n                startup_owner: startup\n                    .as_deref()\n                    .map(|transition| transition.original_owner_identity()),\n                startup_attached: false,\n                previous: request.previous.clone(),\n                current: request.updated.clone(),\n                previous_incarnations: request.previous_incarnations.clone(),\n                current_incarnations: request.updated_incarnations.clone(),\n                previous_activation_heights: request.previous_activation_heights.clone(),\n                current_activation_heights: request.updated_activation_heights.clone(),\n                previous_lineage_root: request.previous_lineage_root,\n                current_lineage_root: request.updated_lineage_root,\n                replaced: replaced.clone(),\n                transition_height: request.transition_height,\n                cursors_updated: false,\n                publish_cursors,\n            });\n        }\n        let original = slot.as_mut().ok_or_else(|| {\n            LaneLifecycleError::Storage("lane geometry operation was not installed".to_owned())\n        })?;\n        if original.tiered.is_none() {\n            let diff = lane_topology_diff(request.previous, request.updated, replaced);\n            original.tiered = Some(\n                self.tiered_backend\n                    .lock()\n                    .prepare_lane_geometry_attempt(\n                        request.previous,\n                        request.updated,\n                        &diff.replacements,\n                        &diff.relabelled,\n                    )\n                    .map_err(|error| {\n                        LaneLifecycleError::Storage(format!("tiered preparation: {error:#}"))\n                    })?,\n            );\n        }\n        if original.raw.is_none() {\n            let lease = self\n                .kura\n                .try_publication_lease()\n                .map_err(geometry_lease_error)?;\n            original.raw = Some(\n                lease\n                    .begin_raw_geometry_attempt(request, replaced, certified)\n                    .map_err(LaneLifecycleError::GeometryStorage)?,\n            );\n        }\n        let raw = original.raw.as_mut().ok_or_else(|| {\n            LaneLifecycleError::Storage("missing retained raw geometry owner".to_owned())\n        })?;\n        if !original.startup_attached {\n            if let Some(startup) = startup.as_deref_mut() {\n                raw.attach_startup_transition(startup)\n                    .map_err(LaneLifecycleError::GeometryStorage)?;\n            }\n            original.startup_attached = true;\n        }\n        // Catalog retry must not send an already chosen publication direction\n        // through apply again. Its completed tiered plan is retained too.\n        if !matches!(\n            raw.phase(),\n            crate::kura::RawGeometryPhase::PublishingCatalog\n                | crate::kura::RawGeometryPhase::CatalogPublished\n        ) {\n            let lease = self\n                .kura\n                .try_publication_lease()\n                .map_err(geometry_lease_error)?;\n            raw.resume_under(&lease)\n                .map_err(LaneLifecycleError::GeometryStorage)?;\n        }\n        original\n            .tiered\n            .as_mut()\n            .ok_or_else(|| {\n                LaneLifecycleError::Storage("missing retained tiered geometry owner".to_owned())\n            })?\n            .resume(&mut self.tiered_backend.lock())\n            .map_err(|error| {\n                LaneLifecycleError::Storage(format!("retained tiered geometry: {error:#}"))\n            })?;\n        if !original.cursors_updated {\n            if let Some(releases) = releases.as_mut() {\n                releases.shard_cursors.write().sync_mapping(request.updated);\n                let should_persist = releases.hydrated.read().is_some();\n                original.cursors_updated = true;\n                if should_persist {\n                    self.persist_lane_lifecycle_cursor_journal(releases);\n                }\n            } else {\n                // Replay geometry has no authority to publish live cursor indexes.\n                original.cursors_updated = true;\n            }\n        }\n        Ok(())\n    }',)),
    ('crates/iroha_core/src/state/geometry_publication.rs', 'method', 'State::rollback_owned_lane_geometry', ('    fn rollback_owned_lane_geometry(\n        &self,\n        previous: &LaneConfig,\n        current: &LaneConfig,\n        incarnations: &BTreeMap<LaneId, Hash>,\n        activation_heights: &BTreeMap<LaneId, u64>,\n        lineage_root: Hash,\n        replaced: &BTreeSet<LaneId>,\n        transition_height: u64,\n        releases: &mut LaneLifecycleReleases<\'_>,\n    ) -> Result<(), LaneLifecycleError> {\n        let mut slot = self.geometry_publication.lock();\n        let original = slot.as_mut().ok_or_else(|| {\n            LaneLifecycleError::Storage(\n                "rollback requires the original retained geometry operation".to_owned(),\n            )\n        })?;\n        if !lane_config_entries_match(&original.previous, previous)\n            || !lane_config_entries_match(&original.current, current)\n            || original.previous_incarnations != *incarnations\n            || original.previous_activation_heights != *activation_heights\n            || original.previous_lineage_root != lineage_root\n            || original.replaced != *replaced\n            || original.transition_height != transition_height\n            || original.startup_owner.is_some()\n        {\n            return Err(LaneLifecycleError::Storage(\n                "rollback differs from its original geometry owner".to_owned(),\n            ));\n        }\n        if let Some(error) = original.raw.as_ref().and_then(|raw| raw.recovery_refusal()) {\n            return Err(LaneLifecycleError::GeometryStorage(error));\n        }\n        // Finish a pending apply write before choosing reversal; the raw owner\n        // refuses to switch direction while that exact write remains unsettled.\n        if original.raw.as_ref().is_some_and(|raw| {\n            raw.has_pending_journal_write()\n                && raw.phase() != crate::kura::RawGeometryPhase::RollingBack\n        }) {\n            return Err(LaneLifecycleError::Storage(\n                "original geometry write must finish before rollback".to_owned(),\n            ));\n        }\n        if let Some(tiered) = original.tiered.as_mut() {\n            tiered\n                .rollback(&mut self.tiered_backend.lock())\n                .map_err(|error| {\n                    LaneLifecycleError::Storage(format!("retained tiered rollback: {error:#}"))\n                })?;\n        }\n        if let Some(raw) = original.raw.as_mut() {\n            let lease = self\n                .kura\n                .try_publication_lease()\n                .map_err(geometry_lease_error)?;\n            raw.rollback_under(&lease)\n                .map_err(LaneLifecycleError::GeometryStorage)?;\n        }\n        if original.publish_cursors {\n            releases.shard_cursors.write().sync_mapping(previous);\n        }\n        *slot = None;\n        if releases.hydrated.read().is_some() {\n            self.persist_lane_lifecycle_cursor_journal(releases);\n        }\n        Ok(())\n    }',)),
    ('crates/iroha_core/src/state/canonical_runtime.rs', 'method', 'State::project_canonical_runtime', ('    pub(super) fn project_canonical_runtime(\n        &self,\n        record: &SnapshotNexusRuntime,\n        world: &impl WorldReadOnly,\n    ) -> Result<CanonicalRuntimeProjection, LaneLifecycleError> {\n        let baseline = self.lane_manifests.read().clone();\n        self.project_canonical_runtime_with_manifests(record, world, &baseline)\n    }',)),
    ('crates/iroha_core/src/state/canonical_runtime.rs', 'method', 'State::project_canonical_runtime_with_manifests', ('    pub(super) fn project_canonical_runtime_with_manifests(\n        &self,\n        record: &SnapshotNexusRuntime,\n        world: &impl WorldReadOnly,\n        baseline: &LaneManifestRegistryHandle,\n    ) -> Result<CanonicalRuntimeProjection, LaneLifecycleError> {\n        let catalog = runtime_catalog_from_world(world)?;\n        let nexus = record.nexus_projection_with_catalog(&self.nexus.read(), catalog.as_ref())?;\n        if let Some(catalog) = &catalog\n            && catalog.baseline_manifests_hash\n                != Hash::prehashed(baseline.baseline_consensus_policy_digest())\n        {\n            return Err(runtime_catalog_invalid(\n                "manifest baseline differs from canonical World catalog",\n            ));\n        }\n        let manifests = if let Some(catalog) = &catalog {\n            Arc::new(\n                baseline\n                    .with_runtime_additions(\n                        &catalog.manifests,\n                        &nexus.lane_catalog,\n                        &nexus.dataspace_catalog,\n                        &nexus.governance,\n                    )\n                    .map_err(runtime_catalog_invalid)?,\n            )\n        } else {\n            rebind_lane_manifests_for_lifecycle(\n                baseline.as_ref(),\n                &nexus.lane_catalog,\n                &nexus.governance,\n            )?\n        };\n        let incarnations = record.active_incarnations()?;\n        let activation_heights = record.active_activation_heights()?;\n        let lineage = record.lineage_projection();\n        validate_lane_incarnation_lineage(\n            &nexus.lane_catalog,\n            &incarnations,\n            &activation_heights,\n            &lineage,\n        )?;\n        let privacy = Arc::new(LanePrivacyRegistry::from_manifest_registry(\n            manifests.as_ref(),\n        ));\n        Ok(CanonicalRuntimeProjection {\n            nexus,\n            incarnations,\n            activation_heights,\n            lineage,\n            samples: record.autoscale_sample_history.iter().copied().collect(),\n            manifests,\n            privacy,\n        })\n    }',)),
