    ('crates/iroha_core/src/state/history_reader_releases.rs', 'struct', 'StateViewReleases', ("pub(crate) struct StateViewReleases<'state> {\n    state: &'state State,\n    pub(super) lifecycle: LaneLifecycleReleases<'state>,\n}",)),
